2	
3	import com.loja.checkout.dto.CheckoutRequest;
4	import com.loja.checkout.dto.CheckoutResponse;
5	import com.loja.checkout.dto.Item;
6	import com.loja.checkout.enums.FormaPagamento;
7	import com.loja.checkout.enums.ModalidadeEntrega;
8	import com.loja.checkout.enums.NivelClube;
9	import com.loja.checkout.enums.Regiao;
10	import com.loja.checkout.exception.CheckoutException;
11	import com.loja.checkout.strategy.CouponStrategyFactory;
12	import com.loja.checkout.strategy.CouponStrategy;
13	import com.loja.checkout.strategy.PaymentAdjustmentStrategy;
14	import com.loja.checkout.strategy.PaymentAdjustmentStrategyFactory;
15	import com.loja.checkout.strategy.ShippingStrategy;
16	import com.loja.checkout.strategy.ShippingStrategyFactory;
17	import com.loja.checkout.util.MoneyRounder;
18	import com.loja.checkout.validation.CheckoutValidator;
19	import java.math.BigDecimal;
20	import java.util.List;
21	import org.springframework.stereotype.Service;
22	
23	@Service
24	public class CheckoutService {
25	
26	    public CheckoutResponse calcularResumo(CheckoutRequest request) {
27	        try {
28	            CheckoutValidator.validar(request);
29	
30	            List<Item> itens = request.getItens();
31	            ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.getModalidadeEntrega());
32	            NivelClube nivel = NivelClube.valueOf(request.getNivelClube());
33	            Regiao regiao = Regiao.valueOf(request.getRegiao());
34	            FormaPagamento forma = FormaPagamento.valueOf(request.getFormaPagamento());
35	            Integer parcelas = (request.getParcelas() != null) ? request.getParcelas() : 1;
36	
37	            BigDecimal subtotalProdutos = calcularSubtotalProdutos(itens);
38	
39	            BigDecimal freteCalculado = calcularFrete(modalidade, itens, nivel);
40	
41	            BigDecimal descontoCupom = calcularDescontoCupom(request.getCupom(), subtotalProdutos, itens, freteCalculado);
42	
43	            BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
44	
45	            BigDecimal totalAntesPagamento = subtotalProdutos
46	                    .subtract(descontoCupom)
47	                    .add(freteCalculado)
48	                    .add(seguro);
49	            totalAntesPagamento = MoneyRounder.round(totalAntesPagamento);
50	
51	            CheckoutValidator.validarFormaPagamentoDisponivel(request.getFormaPagamento(), totalAntesPagamento);
52	
53	            PaymentAdjustmentStrategy paymentStrategy = PaymentAdjustmentStrategyFactory.create(forma);
54	            paymentStrategy.validarParcelas(parcelas);
55	
56	            BigDecimal ajustePagamento = paymentStrategy.calcularAjuste(totalAntesPagamento, parcelas);
57	
58	            BigDecimal totalFinal = totalAntesPagamento.add(ajustePagamento);
59	            totalFinal = MoneyRounder.round(totalFinal);
60	
61	            BigDecimal valorParcela = paymentStrategy.calcularValorParcela(totalAntesPagamento, parcelas);
62	
63	            BigDecimal creditoProximaCompra = calcularCredito(subtotalProdutos, nivel);
64	
65	            boolean temBrinde = verificarBrinde(subtotalProdutos, nivel);
66	
67	            Integer prazoEntrega = obterPrazoEntrega(modalidade);
68	
69	            CheckoutResponse response = new CheckoutResponse();
70	            response.setSubtotalProdutos(MoneyRounder.round(subtotalProdutos));
71	            response.setDescontoCupom(MoneyRounder.round(descontoCupom));
72	            response.setFrete(MoneyRounder.round(freteCalculado));
73	            response.setPrazoEntregaDias(prazoEntrega);
74	            response.setSeguro(MoneyRounder.round(seguro));
75	            response.setAjustePagamento(MoneyRounder.round(ajustePagamento));
76	            response.setTotalFinal(totalFinal);
77	            response.setParcelas(parcelas);
78	            response.setValorParcela(valorParcela);
79	            response.setCreditoProximaCompra(creditoProximaCompra);
80	            response.setBrinde(temBrinde);
81	
82	            return response;
83	        } catch (CheckoutException e) {
84	            throw e;
85	        } catch (Exception e) {
86	            throw new RuntimeException("Erro ao processar checkout", e);
87	        }
88	    }
89	
90	    private BigDecimal calcularSubtotalProdutos(List<Item> itens) {
91	        return itens.stream()
92	                .map(item -> item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())))
93	                .reduce(BigDecimal.ZERO, BigDecimal::add);
94	    }
95	
96	    private BigDecimal calcularPesoTotal(List<Item> itens) {
97	        return itens.stream()
98	                .map(item -> item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())))
99	                .reduce(BigDecimal.ZERO, BigDecimal::add);
100	    }
101	
102	    private BigDecimal calcularFrete(ModalidadeEntrega modalidade, List<Item> itens, NivelClube nivel) {
103	        if (nivel.temFreteGratis()) {
104	            return BigDecimal.ZERO;
105	        }
106	
107	        ShippingStrategy strategy = ShippingStrategyFactory.create(modalidade);
108	        BigDecimal pesoTotal = calcularPesoTotal(itens);
109	        return strategy.calcularFrete(pesoTotal);
110	    }
111	
112	    private BigDecimal calcularDescontoCupom(String cupom, BigDecimal subtotalProdutos, List<Item> itens, BigDecimal freteCalculado) {
113	        if (cupom == null || cupom.isEmpty()) {
114	            return BigDecimal.ZERO;
115	        }
116	
117	        CouponStrategy strategy = CouponStrategyFactory.create(cupom);
118	        if (strategy == null) {
119	            return BigDecimal.ZERO;
120	        }
121	
122	        return strategy.calcularDesconto(subtotalProdutos, itens, freteCalculado);
123	    }
124	
125	    private BigDecimal calcularSeguro(BigDecimal subtotalProdutos, Regiao regiao) {
126	        BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro());
127	        return MoneyRounder.round(seguro);
128	    }
129	
130	    private BigDecimal calcularCredito(BigDecimal subtotalProdutos, NivelClube nivel) {
131	        BigDecimal credito = subtotalProdutos.multiply(nivel.getPercentualCredito());
132	        return MoneyRounder.round(credito);
133	    }
134	
135	    private boolean verificarBrinde(BigDecimal subtotalProdutos, NivelClube nivel) {
136	        if (!nivel.temBrinde()) {
137	            return false;
138	        }
139	        return subtotalProdutos.compareTo(new BigDecimal("500.00")) > 0;
140	    }
141	
142	    private Integer obterPrazoEntrega(ModalidadeEntrega modalidade) {
143	        ShippingStrategy strategy = ShippingStrategyFactory.create(modalidade);
144	        return strategy.getPrazoEntregaDias();
145	    }
146	}
