14	public class CheckoutValidator {
15	
16	    public static void validar(CheckoutRequest request) {
17	        validarPedido(request.getItens());
18	        validarNivelClube(request.getNivelClube());
19	        validarRegiao(request.getRegiao());
20	        validarModalidadeEntrega(request.getModalidadeEntrega());
21	        validarModalidadeDisponivel(request.getItens(), request.getModalidadeEntrega());
22	
23	        BigDecimal subtotal = calcularSubtotal(request.getItens());
24	
25	        validarCupom(request.getCupom(), subtotal, request.getItens());
26	        validarFormaPagamento(request.getFormaPagamento());
27	        validarParcelamento(request.getFormaPagamento(), request.getParcelas());
28	    }
29	
30	    public static void validarFormaPagamentoDisponivel(String formaPagamento, BigDecimal total) {
31	        if (FormaPagamento.BOLETO.name().equals(formaPagamento)) {
32	            if (total.compareTo(new BigDecimal("1000.00")) > 0) {
33	                throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
34	            }
35	        }
36	    }
37	
38	    private static void validarPedido(List<Item> itens) {
39	        if (itens == null || itens.isEmpty()) {
40	            throw new CheckoutException("PEDIDO_INVALIDO");
41	        }
42	
43	        for (Item item : itens) {
44	            if (item.getNome() == null || item.getNome().isEmpty()) {
45	                throw new CheckoutException("PEDIDO_INVALIDO");
46	            }
47	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario().compareTo(BigDecimal.ZERO) <= 0) {
48	                throw new CheckoutException("PEDIDO_INVALIDO");
49	            }
50	            if (item.getQuantidade() == null || item.getQuantidade() <= 0) {
51	                throw new CheckoutException("PEDIDO_INVALIDO");
52	            }
53	            if (item.getPesoKg() == null || item.getPesoKg().compareTo(BigDecimal.ZERO) < 0) {
54	                throw new CheckoutException("PEDIDO_INVALIDO");
55	            }
56	        }
57	    }
58	
59	    private static void validarNivelClube(String nivelClube) {
60	        if (nivelClube == null || nivelClube.isEmpty()) {
61	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
62	        }
63	
64	        try {
65	            NivelClube.valueOf(nivelClube);
66	        } catch (IllegalArgumentException e) {
67	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
68	        }
69	    }
70	
71	    private static void validarRegiao(String regiao) {
72	        if (regiao == null || regiao.isEmpty()) {
73	            throw new CheckoutException("REGIAO_INVALIDA");
74	        }
75	
76	        try {
77	            Regiao.valueOf(regiao);
78	        } catch (IllegalArgumentException e) {
79	            throw new CheckoutException("REGIAO_INVALIDA");
80	        }
81	    }
82	
83	    private static void validarModalidadeEntrega(String modalidade) {
84	        if (modalidade == null || modalidade.isEmpty()) {
85	            throw new CheckoutException("MODALIDADE_INVALIDA");
86	        }
87	
88	        try {
89	            ModalidadeEntrega.valueOf(modalidade);
90	        } catch (IllegalArgumentException e) {
91	            throw new CheckoutException("MODALIDADE_INVALIDA");
92	        }
93	    }
94	
95	    private static void validarModalidadeDisponivel(List<Item> itens, String modalidade) {
96	        if (ModalidadeEntrega.MOTOBOY.name().equals(modalidade)) {
97	            BigDecimal pesoTotal = calcularPesoTotal(itens);
98	            if (pesoTotal.compareTo(new BigDecimal("5.00")) > 0) {
99	                throw new CheckoutException("MODALIDADE_INDISPONIVEL");
100	            }
101	        }
102	    }
103	
104	    private static void validarCupom(String cupom, BigDecimal subtotal, List<Item> itens) {
105	        if (cupom == null || cupom.isEmpty()) {
106	            return;
107	        }
108	
109	        var strategy = CouponStrategyFactory.create(cupom);
110	        if (strategy == null) {
111	            throw new CheckoutException("CUPOM_INVALIDO");
112	        }
113	
114	        if (!strategy.estaAplicavel(subtotal, itens)) {
115	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
116	        }
117	    }
118	
119	    private static void validarFormaPagamento(String formaPagamento) {
120	        if (formaPagamento == null || formaPagamento.isEmpty()) {
121	            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
122	        }
123	
124	        try {
125	            FormaPagamento.valueOf(formaPagamento);
126	        } catch (IllegalArgumentException e) {
127	            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
128	        }
129	    }
130	
131	    private static void validarParcelamento(String formaPagamento, Integer parcelas) {
132	        int parcelasVal = (parcelas != null) ? parcelas : 1;
133	
134	        FormaPagamento forma = FormaPagamento.valueOf(formaPagamento);
135	
136	        if (forma == FormaPagamento.PIX || forma == FormaPagamento.BOLETO) {
137	            if (parcelasVal != 1) {
138	                throw new CheckoutException("PARCELAMENTO_INVALIDO");
139	            }
140	        } else if (forma == FormaPagamento.CARTAO) {
141	            if (parcelasVal < 1 || parcelasVal > 12) {
142	                throw new CheckoutException("PARCELAMENTO_INVALIDO");
143	            }
144	        }
145	    }
146	
147	    private static BigDecimal calcularSubtotal(List<Item> itens) {
148	        return itens.stream()
149	                .map(item -> item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())))
150	                .reduce(BigDecimal.ZERO, BigDecimal::add);
151	    }
152	
153	    private static BigDecimal calcularPesoTotal(List<Item> itens) {
154	        return itens.stream()
155	                .map(item -> item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())))
156	                .reduce(BigDecimal.ZERO, BigDecimal::add);
157	    }
158	}
