6	import java.math.RoundingMode;
7	
8	public class CartaoPayment implements PaymentAdjustmentStrategy {
9	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
10	
11	    @Override
12	    public void validarParcelas(Integer parcelas) {
13	        if (parcelas == null || parcelas < 1 || parcelas > 12) {
14	            throw new IllegalArgumentException("Cartão permite de 1 a 12 parcelas");
15	        }
16	    }
17	
18	    @Override
19	    public BigDecimal calcularAjuste(BigDecimal total, Integer parcelas) {
20	        if (parcelas <= 3) {
21	            return BigDecimal.ZERO;
22	        }
23	
24	        BigDecimal valorParcela = calcularValorParcela(total, parcelas);
25	        BigDecimal valorFinal = valorParcela.multiply(new BigDecimal(parcelas));
26	        BigDecimal ajuste = valorFinal.subtract(total);
27	        return MoneyRounder.round(ajuste);
28	    }
29	
30	    @Override
31	    public BigDecimal calcularValorParcela(BigDecimal total, Integer parcelas) {
32	        if (parcelas <= 3) {
33	            BigDecimal parcela = total.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
34	            return MoneyRounder.round(parcela);
35	        }
36	
37	        BigDecimal n = new BigDecimal(parcelas);
38	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
39	        BigDecimal expoente = umMaisTaxa.pow(-parcelas, new java.math.MathContext(10));
40	        BigDecimal denominador = BigDecimal.ONE.subtract(expoente);
41	        BigDecimal parcela = total.multiply(TAXA_JUROS).divide(denominador, 10, RoundingMode.HALF_EVEN);
42	        return MoneyRounder.round(parcela);
43	    }
44	}
