5	import com.loja.checkout.util.MoneyRounder;
6	import java.math.BigDecimal;
7	import java.util.List;
8	
9	public class Leve3Pague2Coupon implements CouponStrategy {
10	    @Override
11	    public boolean estaAplicavel(BigDecimal subtotalProdutos, List<Item> itens) {
12	        return true;
13	    }
14	
15	    @Override
16	    public BigDecimal calcularDesconto(BigDecimal subtotalProdutos, List<Item> itens, BigDecimal freteCalculado) {
17	        BigDecimal desconto = BigDecimal.ZERO;
18	
19	        for (Item item : itens) {
20	            int quantidade = item.getQuantidade();
21	            int unidadesGratis = quantidade / 3;
22	            BigDecimal descontoItem = item.getPrecoUnitario().multiply(new BigDecimal(unidadesGratis));
23	            desconto = desconto.add(descontoItem);
24	        }
25	
26	        return MoneyRounder.round(desconto);
27	    }
28	}
